SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `residential_country` varchar(100) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `role` enum('admin','owner') NOT NULL DEFAULT 'owner',
  `registry_id` varchar(50) DEFAULT NULL,
  `member_since` varchar(50) DEFAULT 'May 2026',
  `status` varchar(50) DEFAULT 'Active',
  `img` varchar(500) DEFAULT NULL,
  `id_type` varchar(50) DEFAULT NULL,
  `id_last4` varchar(4) DEFAULT NULL,
  `id_doc` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `registry_id` (`registry_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `animals`;
CREATE TABLE `animals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `registry_id` varchar(50) NOT NULL,
  `name` varchar(255) NOT NULL,
  `breed` varchar(255) NOT NULL,
  `gender` varchar(50) DEFAULT 'Male',
  `weight` varchar(50) DEFAULT '25kg',
  `microchip` varchar(50) NOT NULL,
  `date_of_birth` date DEFAULT NULL,
  `color` varchar(255) DEFAULT NULL,
  `rabies_expiration` date DEFAULT NULL,
  `rabies_serial` varchar(100) DEFAULT NULL,
  `rabies_brand` varchar(100) DEFAULT NULL,
  `rabies_type` varchar(100) DEFAULT NULL,
  `facility_name` varchar(255) DEFAULT NULL,
  `trainer_name` varchar(255) DEFAULT NULL,
  `trained_task` varchar(255) DEFAULT NULL,
  `completion_date` date DEFAULT NULL,
  `handler_id` int(11) DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Certified',
  `img` varchar(500) DEFAULT NULL,
  `doc_attestation` varchar(500) DEFAULT NULL,
  `doc_certificate` varchar(500) DEFAULT NULL,
  `doc_id` varchar(500) DEFAULT NULL,
  `doc_other` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `registry_id` (`registry_id`),
  UNIQUE KEY `microchip` (`microchip`),
  KEY `handler_id` (`handler_id`),
  CONSTRAINT `animals_ibfk_1` FOREIGN KEY (`handler_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `travel_requests`;
CREATE TABLE `travel_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `owner_id` int(11) NOT NULL,
  `animal_id` int(11) NOT NULL,
  `travel_date` date NOT NULL,
  `flight_number` varchar(50) NOT NULL,
  `confirmation_number` varchar(50) NOT NULL,
  `route` varchar(100) NOT NULL,
  `status` varchar(50) DEFAULT 'Pending',
  `submitted_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `owner_id` (`owner_id`),
  KEY `animal_id` (`animal_id`),
  CONSTRAINT `travel_requests_ibfk_1` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `travel_requests_ibfk_2` FOREIGN KEY (`animal_id`) REFERENCES `animals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `applications`;
CREATE TABLE `applications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `handler_name` varchar(255) NOT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `country` varchar(100) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `id_type` varchar(50) DEFAULT 'Passport',
  `id_last4` varchar(4) DEFAULT NULL,
  `pet_name` varchar(255) NOT NULL,
  `pet_breed` varchar(255) NOT NULL,
  `pet_gender` varchar(50) DEFAULT 'Male',
  `pet_weight` varchar(50) DEFAULT '25kg',
  `pet_microchip` varchar(50) NOT NULL,
  `pet_dob` date DEFAULT NULL,
  `pet_color` varchar(255) DEFAULT NULL,
  `rabies_expiration` date DEFAULT NULL,
  `rabies_serial` varchar(100) DEFAULT NULL,
  `rabies_brand` varchar(100) DEFAULT NULL,
  `rabies_type` varchar(100) DEFAULT '3-Year Vaccine',
  `facility_name` varchar(255) DEFAULT NULL,
  `trainer_name` varchar(255) DEFAULT NULL,
  `trained_task` varchar(255) DEFAULT NULL,
  `completion_date` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Pending',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `pet_photo` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `activities`;
CREATE TABLE `activities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(50) NOT NULL,
  `description` text NOT NULL,
  `timestamp` varchar(50) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `activities_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `members`;
CREATE TABLE `members` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `registry_id` varchar(50) NOT NULL,
  `region` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Active',
  `contact` varchar(255) DEFAULT NULL,
  `phone` varchar(100) DEFAULT NULL,
  `last_audit` varchar(100) DEFAULT NULL,
  `img` longtext DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `assistance_dog_type` varchar(255) DEFAULT NULL,
  `facility_type` varchar(100) DEFAULT NULL,
  `disabilities_serviced` varchar(500) DEFAULT NULL,
  `demographic_served` varchar(500) DEFAULT NULL,
  `geographical_area` varchar(100) DEFAULT NULL,
  `other_info` text DEFAULT NULL,
  `address` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `registry_id` (`registry_id`)
) ENGINE=InnoDB AUTO_INCREMENT=679 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
